from importlib.metadata import entry_points

def load_user_dao(store: str, cfg: Config) -> UserDao:
    group = entry_points(group="myapp.daos")
    try:
        factory = group[store].load()
    except KeyError:
        raise ValueError(f"no DAO plugin for {store!r}") from None
    return factory(cfg)

